    public virtual void handleOHLCV(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         e: 'kline',
        //         E: 1776095535012,
        //         s: 'ETHUSDT',
        //         p: 'LAST_PRICE',
        //         d: [
        //             {
        //                 t: 1776092400000,
        //                 T: 1776096000000,
        //                 s: 'ETHUSDT',
        //                 i: '1h',
        //                 o: '2234.18',
        //                 c: '2205.15',
        //                 h: '2236.43',
        //                 l: '2199.53',
        //                 v: '12505.60574',
        //                 n: 3381,
        //                 q: '27682528.6655305',
        //                 V: '6420.47929',
        //                 Q: '14213680.1906424'
        //             }
        //         ]
        //     }
        //
        Dictionary<string, object> market = this.getMarketFromClientAndMessage(client, message);
        if ((market == null))
        {
            return;
        }
        object symbol = GetValue(market, "symbol");
        if (!(inOp(this.ohlcvs, symbol)))
        {
            ((IDictionary<string,object>)this.ohlcvs)[(string)symbol] = new Dictionary<string, object>() {};
        }
        List<object> data = this.safeList(message, "d", new List<object>() {});
        IDictionary<string, object> firstEntry = this.safeDict(data, 0, new Dictionary<string, object>() {});
        string? interval = this.safeString(firstEntry, "i");
        string? timeframe = this.findTimeframe(interval);
        object stored = this.safeValue(this.safeValue(this.ohlcvs, symbol), timeframe);
        if ((stored == null))
        {
            Int64? limit = this.safeInteger(this.options, "OHLCVLimit", 1000);
            stored = new ArrayCacheByTimestamp(limit);
            if ((symbol != null) && (timeframe != null))
            {
                ((IDictionary<string,object>)getValue(this.ohlcvs, symbol))[timeframe] = stored;
            }
        }
        for (int i = 0; isLessThan(i, data.Count); postFixIncrement(ref i))
        {
            IDictionary<string, object> entry = this.safeDict(data, i, new Dictionary<string, object>() {});
            List<object> parsed = this.parseWsOHLCV(entry);
            callDynamically(stored, "append", new object[] {parsed});
        }
        string messageHash = add(add(add("ohlcv::", symbol), "::"), timeframe);
        List<object> resolveData = new List<object>() {symbol, timeframe, stored};
        callDynamically(client, "resolve", new object[] {resolveData, messageHash});
    }

    public override List<object> parseWsOHLCV(object ohlcv, object market = null)
    {
        //
        //     {
        //         t: 1776092400000,
        //         T: 1776096000000,
        //         s: 'ETHUSDT',
        //         i: '1h',
        //         o: '2234.18',
        //         c: '2205.15',
        //         h: '2236.43',
        //         l: '2199.53',
        //         v: '12505.60574',
        //         n: 3381,
        //         q: '27682528.6655305',
        //         V: '6420.47929',
        //         Q: '14213680.1906424'
        //     }
        //
        return new List<object> {this.safeInteger(ohlcv, "t"), this.safeNumber(ohlcv, "o"), this.safeNumber(ohlcv, "h"), this.safeNumber(ohlcv, "l"), this.safeNumber(ohlcv, "c"), this.safeNumber(ohlcv, "v")};
    }

