    public virtual void handleMyTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // spot
        //     {
        //         e: 'fill',
        //         E: 1776174283564,
        //         v: 83,
        //         msgEvent: 'OrderUpdate',
        //         d: [
        //             {
        //                 id: '738928502249620072',
        //                 symbol: 'DOGEUSDT',
        //                 baseCoin: 'DOGE',
        //                 quoteCoin: 'USDT',
        //                 orderId: '738928502174122600',
        //                 orderSide: 'SELL',
        //                 fillSize: '200.0',
        //                 fillValue: '19.098000',
        //                 fillFee: '0.01909800',
        //                 direction: 'TAKER',
        //                 createdTime: '1776174283564',
        //                 updatedTime: '1776174283564'
        //             }
        //         ]
        //     }
        //
        // swap
        //     {
        //         "id": "738957755401896296",
        //         "coin": "USDT",
        //         "symbol": "DOGEUSDT",
        //         "orderId": "738957755376730472",
        //         "marginMode": "CROSSED",
        //         "separatedMode": "COMBINED",
        //         "separatedOpenOrderId": "0",
        //         "positionSide": "LONG",
        //         "orderSide": "BUY",
        //         "fillSize": "100",
        //         "fillValue": "9.59500",
        //         "fillFee": "0.00767600",
        //         "liquidateFee": "0",
        //         "realizePnl": "0",
        //         "direction": "TAKER",
        //         "createdTime": "1776181258059",
        //         "updatedTime": "1776181258059"
        //     }
        //
        if (isEqual(this.myTrades, null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            this.myTrades = new ArrayCacheBySymbolById(limit);
        }
        ccxt.pro.ArrayCache trades = this.myTrades;
        List<object> data = this.safeList(message, "d", new List<object>() {});
        Dictionary<string, object> symbols = new Dictionary<string, object>() {};
        for (int i = 0; isLessThan(i, data.Count); postFixIncrement(ref i))
        {
            IDictionary<string, object> trade = this.safeDict(data, i, new Dictionary<string, object>() {});
            Dictionary<string, object> parsed = this.parseWsMyTrade(trade);
            object symbol = GetValue(parsed, "symbol");
            if ((symbol != null))
            {
                symbols[(string)symbol] = true;
            }
            callDynamically(trades, "append", new object[] {parsed});
        }
        string messageHash = "myTrades";
        List<object> symbolKeys = new List<object>(((IDictionary<string,object>)symbols).Keys);
        Dictionary<string, object> market = this.getMarketFromSymbols(symbolKeys);
        if (isEqual(GetValue(market, "contract"), true))
        {
            messageHash = "myContractTrades";
        }
        for (int j = 0; isLessThan(j, symbolKeys.Count); postFixIncrement(ref j))
        {
            object symbol = getValue(symbolKeys, j);
            string symbolMessageHash = add(add(messageHash, "::"), symbol);
            callDynamically(client, "resolve", new object[] {trades, symbolMessageHash});
        }
        callDynamically(client, "resolve", new object[] {trades, messageHash});
    }

    public virtual Dictionary<string, object> parseWsMyTrade(object trade, IDictionary<string, object> market = null)
    {
        //
        // spot
        //     {
        //         id: '738928502249620072',
        //         symbol: 'DOGEUSDT',
        //         baseCoin: 'DOGE',
        //         quoteCoin: 'USDT',
        //         orderId: '738928502174122600',
        //         orderSide: 'SELL',
        //         fillSize: '200.0',
        //         fillValue: '19.098000',
        //         fillFee: '0.01909800',
        //         direction: 'TAKER',
        //         createdTime: '1776174283564',
        //         updatedTime: '1776174283564'
        //     }
        //
        Int64? timestamp = this.safeInteger(trade, "createdTime");
        string? marketId = this.safeString(trade, "symbol");
        string marketType = "spot";
        string? positionSide = this.safeString(trade, "positionSide");
        if ((positionSide != null))
        {
            marketType = "swap";
        }
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, null, null, marketType);
        market = marketResolved;
        string? side = this.safeStringLower(trade, "orderSide");
        Dictionary<string, object> fee = null;
        string? commission = this.safeString(trade, "fillFee");
        if ((commission != null))
        {
            string? commissionAsset = this.safeString(trade, "coin");
            object feeCurrency = this.safeCurrencyCode(commissionAsset);
            if (marketType == "spot")
            {
                if (side == "buy")
                {
                    feeCurrency = GetValue(marketResolved, "base");
                } else
                {
                    feeCurrency = GetValue(marketResolved, "quote");
                }
            }
            fee = new Dictionary<string, object>() {
                { "cost", commission },
                { "currency", feeCurrency },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeString(trade, "id") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", GetValue(marketResolved, "symbol") },
            { "order", this.safeString(trade, "orderId") },
            { "type", this.safeString(trade, "type") },
            { "side", side },
            { "takerOrMaker", this.safeStringLower(trade, "direction") },
            { "price", null },
            { "amount", this.safeString(trade, "fillSize") },
            { "cost", this.safeString(trade, "fillValue") },
            { "fee", fee },
        });
    }

